JOIN tag t ON n.tag = t.tag AND n.version = t.version
WHERE n.ddate BETWEEN 20220101 AND 20221231 AND n.value IS NOT NULL
      AND t.custom = 0
GROUP BY n.tag, t.tlabel, t.datatype
HAVING COUNT(DISTINCT n.adsh) > 100
ORDER BY num_filings DESC
LIMIT 500;

-- Q39: joins=1, agg=True, sub=False, tables=3, rows=183, time=437.0ms
SELECT s.form, n.tag,
       COUNT(*) AS cnt,
       MIN(n.value) AS min_val,
       MAX(n.value) AS max_val,
       AVG(n.value) AS avg_val
FROM num n
JOIN sub s ON n.adsh = s.adsh
WHERE n.uom = 'pure' AND n.qtrs = 0
      AND n.value IS NOT NULL AND n.value != 0
GROUP BY s.form, n.tag
HAVING COUNT(*) > 50
ORDER BY cnt DESC
LIMIT 1000;

-- Q40: joins=3, agg=True, sub=False, tables=4, rows=100, time=452.2ms
